      if (b.escudo && b.recurso === "vida" && max > 0) { const es = naurenHudLerRecurso(actor, "escudo").value; if (es > 0 && !vert) svg += `<rect x="${x + W * frac}" y="${y}" width="${W * Math.min(1 - frac, es / max)}" height="${H}" fill="#d9d0f5"/>`; }
