    const barraH = b => `<div class="nauren-car-hbar" title="${e(b.nome)} ${e(b.texto)}"><div style="width:${b.pct}%;background:linear-gradient(90deg,${e(b.cor1)},${e(b.cor2)})"></div></div>`;
